const cfg = $('Configuración').first().json;
const base = String(cfg.api_base).replace(/\/+$/, '');
const peticion = async (metodo, ruta, cuerpo, clave) => {
  const opciones = { method: metodo, url: base + ruta, json: true, ignoreHttpStatusErrors: true, returnFullResponse: true,
    headers: { Authorization: 'Bearer ' + cfg.api_token, ...(clave ? { 'Idempotency-Key': clave } : {}) } };
  if (cuerpo) opciones.body = cuerpo;
  const r = await this.helpers.httpRequest(opciones);
  if (r.statusCode >= 400) {
    const err = (r.body && r.body.error) || {};
    throw new Error((err.code ? err.code + ': ' : 'HTTP ' + r.statusCode + ': ') + (err.message || 'error') + (err.how_to_fix ? ' → ' + err.how_to_fix : ''));
  }
  return r.body;
};
const dormir = (ms) => new Promise((r) => setTimeout(r, ms));
const limpiar = (t) => String(t).replace(/[^A-Za-z0-9_\-:.]/g, '-').slice(0, 24);
// Espera a que TODOS los trabajos terminen. Devuelve {ok, trabajos, coste} o {ok:false, motivo}.
const esperar = async (ids) => {
  const limite = Date.now() + Number(cfg.espera_maxima_min || 20) * 60000;
  let coste = 0;
  for (;;) {
    const estados = [];
    for (const id of ids) estados.push(await peticion('GET', '/jobs/' + id));
    const mal = estados.find((j) => j.status === 'failed' || j.status === 'canceled');
    if (mal) return { ok: false, motivo: 'Falló ' + mal.id + ': ' + ((mal.error && mal.error.message) || mal.status) };
    if (estados.every((j) => j.status === 'succeeded')) {
      coste = estados.reduce((s, j) => s + Number((j.cost && j.cost.final) || 0), 0);
      return { ok: true, trabajos: estados, coste };
    }
    if (Date.now() > limite) return { ok: false, motivo: 'Tiempo de espera agotado' };
    await dormir(Number(cfg.sondeo_s || 5) * 1000);
  }
};

// 1) Una fila = una idea. Reparte el guion en escenas y ESTIMA el coste total sin generar nada.
const fila = $input.first().json;
const tema = String(fila.tema || '').trim();
const guion = String(fila['guion corto'] || fila.guion || '').trim();
const formato = String(fila.formato || cfg.formato_defecto || '9:16').trim();
const maxCost = Number(fila.max_cost || cfg.max_cost_defecto);
const base_fila = { row_number: fila.row_number, tema, guion, formato, max_cost: maxCost };
if (!tema || !guion) return [{ json: { ...base_fila, ok: false, motivo: 'Faltan el tema o el guion corto' } }];
if (!['9:16', '16:9', '1:1'].includes(formato)) return [{ json: { ...base_fila, ok: false, motivo: 'Formato no válido: usa 9:16, 16:9 o 1:1' } }];
const n = Number(cfg.escenas || 3);
const frases = guion.split(/(?<=[.!?…])\s+/).filter(Boolean);
const escenas = Array.from({ length: n }, (_, i) => {
  const frase = frases[Math.min(Math.floor((i * frases.length) / n), frases.length - 1)];
  return { prompt_imagen: `${tema}. ${frase}. ${cfg.estilo}`, prompt_video: `${frase} — ${cfg.movimiento}` };
});
const plantilla = formato === '9:16' ? 'ugc_tiktok' : formato === '1:1' ? 'cuadrado_social' : 'anuncio_producto';
let coste = 0;
for (const e of escenas) {
  const ei = await peticion('POST', '/estimates', { type: 'image', model: cfg.modelo_imagen, params: { prompt: e.prompt_imagen, aspect_ratio: formato } });
  const ev = await peticion('POST', '/estimates', { type: 'video', model: cfg.modelo_video,
    params: { prompt: e.prompt_video, image_url: 'https://example.com/estimacion.png', duration: Number(cfg.duracion_clip), resolution: cfg.resolucion_video, aspect_ratio: formato } });
  if (ei.estimated_cost == null || ev.estimated_cost == null) {
    return [{ json: { ...base_fila, ok: false, motivo: 'No se puede estimar el coste de este modelo' } }];
  }
  coste += ei.estimated_cost + ev.estimated_cost;
}
coste = Math.round(coste * 10000) / 10000;
const clave = limpiar(`${cfg.prefijo_clave}-${fila.row_number}-${tema}`);
return [{ json: { ...base_fila, ok: coste <= maxCost, motivo: coste <= maxCost ? '' : `Coste estimado $${coste.toFixed(2)} > max_cost $${maxCost.toFixed(2)}`,
  escenas, plantilla, coste_estimado: coste, clave } }];

