// 2) Crea las imágenes (una por escena). Idempotency-Key: si n8n reintenta el nodo, NO se cobra dos veces.
const fila = $input.first().json;
const ids = [];
for (let i = 0; i < fila.escenas.length; i++) {
  const r = await peticion('POST', '/jobs', { type: 'image', model: cfg.modelo_imagen, max_cost: fila.max_cost,
    params: { prompt: fila.escenas[i].prompt_imagen, aspect_ratio: fila.formato, n: 1, name: `escena-${i + 1}` },
    metadata: { fila: fila.row_number, escena: i + 1 } }, `${fila.clave}-img${i + 1}`);
  ids.push(r.id);
}
const fin = await esperar(ids);
if (!fin.ok) return [{ json: { ...fila, ok: false, motivo: fin.motivo } }];
return [{ json: { ...fila, ok: true, imagenes: ids, coste_imagenes: fin.coste } }];

