// 4) Montaje local con la plantilla vertical (gratis) y los subtítulos del guion. El webhook vuelve a ESTE flujo (nodo Wait).
const fila = $input.first().json;
const r = await peticion('POST', '/jobs', { type: 'montage',
  params: { clips: fila.videos, template: fila.plantilla, title: fila.tema, captions: fila.guion, name: fila.tema },
  webhook: { url: $execution.resumeUrl }, metadata: { fila: fila.row_number } }, `${fila.clave}-montaje`);
return [{ json: { ...fila, montaje_id: r.id } }];

