// 5) Prepara lo que se escribe en la hoja: enlace, coste real (según las tablas de la app) y estado.
const fila = $('Montaje').first().json;
const recibido = $('Esperar webhook').first().json;
const job = (recibido.body && recibido.body.job) || recibido.job || {};
let enlace = '';
try { enlace = $('Subir a Drive').first().json.webViewLink || ''; } catch (e) { enlace = ''; }
const ok = job.status === 'succeeded';
const coste = Math.round(((fila.coste_imagenes || 0) + (fila.coste_videos || 0)) * 10000) / 10000;
return [{ json: { row_number: fila.row_number, estado: ok ? 'listo' : 'error', video_url: ok ? (enlace || `${base}/jobs/${job.id}/files/1`) : '',
  coste_real: coste, coste_estimado: fila.coste_estimado, job_id: job.id || fila.montaje_id,
  notas: ok ? '' : ((job.error && job.error.message) || 'El montaje falló') } }];

const f = $input.first().json;
return [{ json: { row_number: f.row_number, estado: f.coste_estimado ? 'rechazada (coste)' : 'error', video_url: '',
  coste_real: 0, coste_estimado: f.coste_estimado || '', job_id: '', notas: f.motivo || 'No se pudo procesar la fila' } }];

const f = $input.first().json;
return [{ json: { row_number: f.row_number, estado: 'error', video_url: '', coste_real: (f.coste_imagenes || 0) + (f.coste_videos || 0), coste_estimado: f.coste_estimado || '',
  job_id: '', notas: f.motivo || 'Error en la generación' } }];
